import heapq


def dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    domains = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name]
                          if row["version"] not in blocked.get(name, [])
                          and (name not in pins or row["version"] == pins[name]))
        domains.append((versions if preference == "maximum" else []) +
                       ([-1] if preference == "maximum" else []) +
                       (versions if preference == "minimum" else []))

    roots = data.get("roots", {})
    best = None
    best_vector = None
    for values in product(*domains):
        chosen = dict(zip(names, values))
        chosen = {name: version for name, version in chosen.items() if version != -1}
        if any(name not in chosen or not low <= chosen[name] <= high
               for name, (low, high) in roots.items()):
            continue
        edges = {name: [] for name in chosen}
        valid = True
        for name, version in chosen.items():
            row = next(row for row in packages[name] if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in chosen or not dep["min"] <= chosen[target] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue
        reachable = set()
        todo = list(roots)
        while todo:
            node = todo.pop()
            if node in reachable:
                continue
            if node not in chosen:
                valid = False
                break
            reachable.add(node)
            todo.extend(edges[node])
        if not valid or reachable != set(chosen):
            continue
        state, finished = set(), set()
        def visit(node):
            if node in state:
                return False
            if node in finished:
                return True
            state.add(node)
            if any(not visit(child) for child in edges[node]):
                return False
            state.remove(node)
            finished.add(node)
            return True
        if not all(visit(node) for node in edges):
            continue
        vector = tuple(chosen.get(name, -1) for name in names)
        if best_vector is None or (vector > best_vector if preference == "maximum"
                                   else vector < best_vector):
            best, best_vector = chosen, vector
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def ledger(data):
    winners = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        key = event.get("id", "anonymous:" + str(pos))
        rank = (event.get("revision", 0), pos)
        if key not in winners or rank > winners[key][0]:
            winners[key] = (rank, event)
    balances = dict(data.get("opening", {}))

    def rounded(n, d):
        if data["rounding"] == "half_up":
            return (n + d // 2) // d
        return n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def quota_intervals(data):
    jobs = [j for j in data["jobs"] if j["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    for subset in combinations(jobs, data["k"]):
        ids = {j["id"] for j in subset}
        if not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        active = []
        valid = True
        for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                valid = False
                break
        if not valid:
            continue
        selected = sorted(ids)
        value = sum(j["value"] for j in subset)
        if best_value is None or value > best_value or (value == best_value and selected < best_ids):
            best_ids, best_value = selected, value
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def temporal_routes(data):
    required = data.get("required", [])
    bits = {node: sum(1 << i for i, r in enumerate(required) if r == node)
            for node in range(data["n"])}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial = (source, bits[source], data["coupons"])
    dist = {initial: data["start"]}
    queue = [(data["start"], source, bits[source], data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                choices.append((max(2, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bits[nxt]
                next_state = (nxt, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


